  15	
  16	// ── Types ────────────────────────────────────────────────────────────────────
  17	
  18	export interface BatchIndexerOptions {
  19	  /** Base path for resolving relative paths */
  20	  basePath: string;
  21	  /** Maximum concurrent file processing operations (default: 8) */
  22	  concurrency?: number;
  23	  /** Options passed to TypeScriptLoader */
