  70	
  71	export interface IncrementalIndexResult extends BatchIndexResult {
  72	  /** Files that were re-indexed due to changes */
  73	  filesUpdated: number;
  74	  /** Files unchanged since last index (skipped) */
  75	  filesUnchanged: number;
  76	}
