  83	// ── Constants ────────────────────────────────────────────────────────────────
  84	
  85	const DEFAULT_CONCURRENCY = 8;
  86	const TS_EXTENSIONS = new Set([".ts", ".tsx", ".mts", ".cts"]);
  87	
  88	// ── Batch Indexer ────────────────────────────────────────────────────────────
  89	
  90	export class BatchIndexer {
  91	  private tsLoader: TypeScriptLoader;
  92	  private textLoader: TextLoader;
  93	  private concurrency: number;
  94	  private onFileIndexed: ((info: FileIndexedInfo) => void) | null;
  95	  private onFileError: ((info: FileErrorInfo) => void) | null;
  96	
  97	  constructor(options: BatchIndexerOptions) {
  98	    if (!options.basePath) {
  99	      throw new RAGError("LOADER_ERROR", "basePath is required");
 100	    }
 101	
 102	    this.concurrency = options.concurrency ?? DEFAULT_CONCURRENCY;
 103	    this.onFileIndexed = options.onFileIndexed ?? null;
 104	    this.onFileError = options.onFileError ?? null;
 105	
 106	    this.tsLoader = new TypeScriptLoader({
 107	      basePath: options.basePath,
 108	      ...options.typescript,
 109	    });
 110	
 111	    this.textLoader = new TextLoader({
 112	      basePath: options.basePath,
 113	      ...options.text,
 114	    });
 115	  }
 116	
 117	  /**
 118	   * Process all given file paths concurrently and return indexed documents.
 119	   */
 120	  async index(filePaths: string[]): Promise<BatchIndexResult> {
 121	    const start = Date.now();
 122	    const documents: VectorDocumentInput[] = [];
 123	    let filesProcessed = 0;
 124	    let filesFailed = 0;
 125	    let filesSkipped = 0;
 126	
 127	    await runConcurrent(filePaths, this.concurrency, async (filePath, i) => {
 128	      const loader = this.selectLoader(filePath);
 129	      if (!loader) {
 130	        filesSkipped++;
 131	        return;
 132	      }
 133	
 134	      try {
 135	        const docs = await loader.load(filePath);
 136	        if (docs.length === 0) {
 137	          filesSkipped++;
 138	          return;
 139	        }
 140	
 141	        filesProcessed++;
 142	        documents.push(...docs);
 143	
 144	        if (this.onFileIndexed) {
 145	          this.onFileIndexed({
 146	            filePath,
 147	            documentCount: docs.length,
 148	            filesProcessedSoFar: filesProcessed,
 149	            totalFiles: filePaths.length,
 150	          });
 151	        }
 152	      } catch (err) {
 153	        filesFailed++;
 154	        if (this.onFileError) {
 155	          this.onFileError({
 156	            filePath,
 157	            error: err,
 158	            filesProcessedSoFar: filesProcessed + filesFailed,
 159	            totalFiles: filePaths.length,
 160	          });
 161	        }
 162	      }
 163	    });
 164	
 165	    return {
 166	      documents,
 167	      filesProcessed,
 168	      filesFailed,
 169	      filesSkipped,
 170	      chunksProduced: documents.length,
 171	      durationMs: Date.now() - start,
 172	    };
 173	  }
 174	
 175	  /**
 176	   * Incremental index — only re-index files whose mtime has changed.
 177	   *
 178	   * Returns the result plus an updated change map for the next run.
 179	   */
 180	  async indexIncremental(
 181	    filePaths: string[],
 182	    options?: IncrementalIndexOptions,
 183	  ): Promise<{ result: IncrementalIndexResult; changes: FileChangeMap }> {
 184	    const start = Date.now();
 185	    const previousChanges = options?.previousChanges ?? new Map<string, number>();
 186	    const currentChanges: FileChangeMap = new Map();
 187	    const documents: VectorDocumentInput[] = [];
 188	    let filesProcessed = 0;
 189	    let filesFailed = 0;
 190	    let filesSkipped = 0;
 191	    let filesUpdated = 0;
 192	    let filesUnchanged = 0;
 193	
 194	    // Phase 1: Check which files have changed
 195	    const filesToProcess: string[] = [];
 196	    const mtimeResults = await Promise.allSettled(
 197	      filePaths.map(async (fp) => {
 198	        const s = await stat(fp);
 199	        return { filePath: fp, mtimeMs: s.mtimeMs };
 200	      }),
 201	    );
 202	
 203	    for (const result of mtimeResults) {
 204	      if (result.status === "rejected") {
 205	        filesSkipped++;
 206	        continue;
 207	      }
 208	
 209	      const { filePath, mtimeMs } = result.value;
 210	      currentChanges.set(filePath, mtimeMs);
 211	
 212	      const previousMtime = previousChanges.get(filePath);
 213	      if (previousMtime !== undefined && previousMtime >= mtimeMs) {
 214	        filesUnchanged++;
 215	        continue;
 216	      }
 217	
 218	      filesToProcess.push(filePath);
 219	    }
 220	
 221	    // Phase 2: Load only changed files concurrently
 222	    await runConcurrent(filesToProcess, this.concurrency, async (filePath) => {
 223	      const loader = this.selectLoader(filePath);
 224	      if (!loader) {
 225	        filesSkipped++;
 226	        return;
 227	      }
 228	
 229	      try {
 230	        const docs = await loader.load(filePath);
 231	        if (docs.length === 0) {
 232	          filesSkipped++;
 233	          return;
 234	        }
 235	
 236	        filesProcessed++;
 237	        filesUpdated++;
 238	        documents.push(...docs);
 239	
 240	        if (this.onFileIndexed) {
 241	          this.onFileIndexed({
 242	            filePath,
 243	            documentCount: docs.length,
 244	            filesProcessedSoFar: filesProcessed,
 245	            totalFiles: filesToProcess.length,
 246	          });
 247	        }
 248	      } catch (err) {
 249	        filesFailed++;
 250	        if (this.onFileError) {
 251	          this.onFileError({
 252	            filePath,
 253	            error: err,
 254	            filesProcessedSoFar: filesProcessed + filesFailed,
 255	            totalFiles: filesToProcess.length,
 256	          });
 257	        }
 258	      }
 259	    });
 260	
 261	    const result: IncrementalIndexResult = {
 262	      documents,
 263	      filesProcessed,
 264	      filesFailed,
 265	      filesSkipped,
 266	      chunksProduced: documents.length,
 267	      durationMs: Date.now() - start,
 268	      filesUpdated,
 269	      filesUnchanged,
 270	    };
 271	
 272	    return { result, changes: currentChanges };
 273	  }
 274	
 275	  /**
 276	   * Select the appropriate loader for a file based on its extension.
 277	   */
 278	  private selectLoader(filePath: string): TypeScriptLoader | TextLoader | null {
 279	    const ext = extname(filePath).toLowerCase();
 280	
 281	    if (TS_EXTENSIONS.has(ext) && this.tsLoader.canHandle(filePath)) {
 282	      return this.tsLoader;
 283	    }
 284	
 285	    if (this.textLoader.canHandle(filePath)) {
 286	      return this.textLoader;
 287	    }
 288	
 289	    return null;
 290	  }
 291	}
