 293	// ── Concurrency Utility ──────────────────────────────────────────────────────
 294	
 295	/**
 296	 * Run async `task` over `items` with at most `limit` concurrent operations.
 297	 * Preserves input order for results, not execution order.
 298	 */
 299	async function runConcurrent<T>(
 300	  items: T[],
 301	  limit: number,
 302	  task: (item: T, index: number) => Promise<void>,
 303	): Promise<void> {
 304	  let nextIndex = 0;
 305	
 306	  async function worker(): Promise<void> {
 307	    while (nextIndex < items.length) {
 308	      const idx = nextIndex++;
 309	      await task(items[idx], idx);
 310	    }
 311	  }
 312	
 313	  const workers = Array.from(
 314	    { length: Math.min(limit, items.length) },
 315	    () => worker(),
 316	  );
 317	
 318	  await Promise.all(workers);
 319	}
 320	
