 200	/**
 201	 * Detect binary content by checking for null bytes in the buffer.
 202	 */
 203	function isBinaryContent(buffer: Buffer): boolean {
 204	  for (let i = 0; i < buffer.length; i++) {
 205	    if (buffer[i] === 0) return true;
 206	  }
 207	  return false;
