 210	/**
 211	 * Strip leading comment lines (shebang, block comments) from source text.
 212	 * Preserves content after the initial comment block.
 213	 */
 214	function stripLeadingComments(content: string): string {
 215	  const lines = content.split("\n");
 216	  let i = 0;
 217	  let inBlockComment = false;
 218	
 219	  while (i < lines.length) {
 220	    const trimmed = lines[i].trim();
 221	
 222	    if (trimmed.startsWith("#!")) {
 223	      i++;
 224	      continue;
 225	    }
 226	
 227	    if (trimmed.startsWith("/*")) {
 228	      inBlockComment = true;
 229	      if (trimmed.includes("*/")) {
 230	        inBlockComment = false;
 231	        i++;
 232	        continue;
 233	      }
 234	      i++;
 235	      continue;
 236	    }
 237	
 238	    if (inBlockComment) {
 239	      if (trimmed.includes("*/")) {
 240	        inBlockComment = false;
 241	      }
 242	      i++;
 243	      continue;
 244	    }
 245	
 246	    if (trimmed.startsWith("//") || trimmed.startsWith("#")) {
 247	      i++;
 248	      continue;
 249	    }
 250	
 251	    break;
 252	  }
 253	
 254	  return lines.slice(i).join("\n");
 255	}
