 257	/**
 258	 * Split text into overlapping chunks, breaking at paragraph/sentence boundaries.
 259	 */
 260	function chunkText(text: string, chunkSize: number, overlap: number): string[] {
 261	  if (text.length <= chunkSize) return [text];
 262	
 263	  const chunks: string[] = [];
 264	  let start = 0;
 265	
 266	  while (start < text.length) {
 267	    let end = Math.min(start + chunkSize, text.length);
 268	
 269	    if (end < text.length) {
 270	      const slice = text.slice(start, end);
 271	      const paragraphBreak = slice.lastIndexOf("\n\n");
 272	      const sentenceBreak = slice.lastIndexOf(". ");
 273	
 274	      if (paragraphBreak > chunkSize * 0.5) {
 275	        end = start + paragraphBreak + 2;
 276	      } else if (sentenceBreak > chunkSize * 0.5) {
 277	        end = start + sentenceBreak + 2;
 278	      }
 279	    }
 280	
 281	    chunks.push(text.slice(start, end).trim());
 282	
 283	    const nextStart = end - overlap;
 284	    if (nextStart <= start) {
 285	      start = end;
 286	    } else {
 287	      start = nextStart;
 288	    }
 289	  }
 290	
 291	  return chunks.filter((c) => c.length > 0);
 292	}
 293	
 294	// ── Factory ──────────────────────────────────────────────────────────────────
 295	
 296	export function createTextLoader(options: TextLoaderOptions): TextLoader {
 297	  return new TextLoader(options);
 298	}
